<div x-data="{ open:false, title:'Konfirmasi', message:'', confirmLabel:'Lanjutkan', tone:'brand', action:null, show(event) { const d=event.detail || {}; this.title=d.title || 'Konfirmasi'; this.message=d.message || 'Apakah Anda yakin?'; this.confirmLabel=d.confirmLabel || 'Lanjutkan'; this.tone=d.tone || 'brand'; this.action=d.onConfirm || null; this.open=true }, proceed() { const callback=this.action; this.open=false; if (typeof callback === 'function') this.$nextTick(() => callback()) } }" @confirm-dialog.window="show($event)" @keydown.escape.window="open=false" x-show="open" x-cloak class="fixed inset-0 z-[100001] flex items-center justify-center p-4" role="dialog" aria-modal="true">
    <div class="absolute inset-0 bg-gray-950/55 backdrop-blur-[2px]" @click="open=false"></div>
    <div x-show="open" x-transition class="relative w-full max-w-md rounded-2xl border border-gray-200 bg-white p-6 shadow-theme-xl">
        <div class="flex items-start gap-4"><span class="flex size-11 shrink-0 items-center justify-center rounded-xl" :class="tone === 'danger' ? 'bg-error-50 text-error-600' : 'bg-brand-50 text-brand-600'"><svg class="size-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 8v5m0 3h.01M10.3 3.8 2.5 17.3A2 2 0 0 0 4.2 20h15.6a2 2 0 0 0 1.7-2.7L13.7 3.8a2 2 0 0 0-3.4 0Z"/></svg></span><div><h2 class="text-lg font-semibold text-gray-900" x-text="title"></h2><p class="mt-2 text-sm leading-6 text-gray-600" x-text="message"></p></div></div>
        <div class="mt-6 flex justify-end gap-3"><button type="button" class="crud-btn-secondary" @click="open=false">Batal</button><button type="button" class="crud-btn-primary" :class="tone === 'danger' ? '!bg-error-600 hover:!bg-error-700' : ''" @click="proceed()" x-text="confirmLabel"></button></div>
    </div>
</div>
